export const AGENT_TOTAL = AGENTS.length;

const _AGENT_INDEX = new Map(AGENTS.map((a) => [a.id, a]));

export function getAgentById(id) {
  if (!id) return null;
  return _AGENT_INDEX.get(id) || null;
}
